import zlib

# Copiez ici la valeur de payload_data depuis le fichier (entièrement)
payload_data = ""

# Récupérez la valeur de config_salt depuis le fichier
config_salt = "6366675f73616c745f32303234"

b = bytes.fromhex(config_salt)
d = bytearray(a ^ b[i % len(b)] for i, a in enumerate(bytes.fromhex(payload_data)))
code = zlib.decompress(d).decode('utf-8')

# Sauvegardez le code décompressé dans un fichier pour l'analyser
with open("decompressed_task.py", "w", encoding="utf-8") as f:
    f.write(code)

print("Code extrait avec succès dans decompressed_task.py")
